ProjectALife.DialogueShards["scenes_plan_3"] = {
{"fw_ld5_meds_c018","plan",2,"reg=civilian,family,worker,rescue|day=2,30|mood=calm",{1,"Nobody's had a tetanus shot since 1988, that's me, that's you",2,"Fine, then we don't get cut, nobody gets cut",1,"Nobody gets cut? Out here? Come on!",2,"...The clinic, then, there's got to be a box of tetanus in the fridge, if the fridge still works"}},
{"fw_ld5_meds_c019","plan",2,"reg=civilian,family,worker,rescue|day=1,14|mood=calm",{1,"My glasses broke, I can't see my own hand",2,"Eye doctor on Elm, there's a drawer of old frames in the front",1,"Frames don't have the right prescription",2,"So you walk into the wall with a pair that's close, or you walk into it with nothing"}},
{"fw_ld5_batt_c020","plan",2,"reg=civilian,family,worker,rescue|mood=calm",{1,"Take the batteries out of every remote control in the house",2,"The TV remote doesn't work anyway",1,"Exactly, the VCR one, the garage door, the kitchen clock, the alarm clock upstairs",2,"I'm on it, that's eight AAs right there, I feel like a genius"}},
{"fw_ld5_batt_c021","plan",2,"reg=civilian,family,worker,rescue|mood=funny",{1,"Smoke detectors have nine-volt batteries in them, did you know that?",2,"Not when it's beeping at three in the morning",1,"Now it's gonna save our lives for real, go pull every one, bring a chair",2,"Chair, ladder, I'll do the whole house, I hate those things anyway"}},
{"fw_ld5_batt_c022","plan",2,"reg=worker|mood=calm",{1,"Could a car battery run a radio or a small light?",2,"Maybe, with the right equipment. Finding a truck doesn't mean its battery's good",1,"I'd want someone who knew the wiring before we tried it",2,"And a way to carry it. Let's not wreck something useful by guessing"}},
{"fw_ld5_gas_c023","plan",2,"reg=civilian,family,worker,rescue|mood=calm",{1,"Every garage has a gas can, and every lawn mower has a half-gallon in the damn tank",2,"Mowers! I never thought of mowers",1,"So we walk the street, one garage at a time, take the mower gas, leave the can",2,"That's got to be eight gallons by the end of the street"}},
{"fw_ld5_gas_c024","plan",2,"reg=worker|mood=calm",{1,"Farmer Boyd's got a red diesel tank, a big one, for the tractors",2,"Diesel doesn't go in a truck that wants gas",1,"It does if the truck's a diesel, Boyd's is, Boyd's got three",2,"We ask Boyd, and if he's not there we leave a note"}},
{"fw_ld5_gas_c025","plan",2,"reg=civilian,family,worker,rescue|mood=angry",{1,"Truck's on fumes, we walk, and the truck sits there, there's a whole tank under that parking lot",2,"Under the lot ain't in the damn truck, genius",1,"I know that! A hose, a bucket, I've done it before!",2,"Then do it, Larry, I'm tired of hearing about it"}},
{"fw_ld5_gas_c026","plan",2,"reg=civilian,family,worker,rescue|day=4,40|mood=grim",{1,"Old man at the Citgo said gas goes bad in six months",2,"It's been two weeks",1,"So it's fine, and nobody's gonna check, we take what's there",2,"Take what's there, and if the truck chokes, we blame the old man"}},
{"fw_ld5_gas_c027","plan",2,"reg=civilian,family,worker,rescue|day=1,30|mood=calm",{1,"How would you work out how long a generator could run?",2,"Count the fuel?",1,"Count it, then find out what that generator actually uses. Not a number somebody remembers",2,"And make a plan for when it's gone. I don't want lights becoming something we can't live without"}},
{"fw_ld5_scout_c028","plan",3,"reg=civilian,family,worker,rescue|mood=funny",{1,"Somebody has to scout the Dairy Bar, we flip for it",2,"I'm not flipping",3,"I'll go, I'm the fastest",1,"You're the fastest at eating, Dennis, sit down",2,"Flip the damn coin, loser goes",3,"...Heads"}},
{"fw_ld5_scout_c029","plan",2,"reg=civilian,family,worker,rescue|mood=calm",{1,"I go alone, I'm quieter",2,"You're not quieter, you hum when you're nervous",1,"I don't hum",2,"You're humming right now"}},
{"fw_ld5_scout_c030","plan",2,"reg=civilian,family,worker,rescue|x2=f|mood=grim",{1,"Nobody goes alone, not to the outhouse, not anywhere",2,"That's a lot of walking in pairs, Sue",1,"I buried a man who went alone, I'm not doing it twice",2,"...Pairs, fine, I'll go to the bathroom with whoever you pick"}},
{"fw_ld5_scout_c031","plan",2,"reg=civilian,family,worker,rescue|mood=calm",{1,"One whistle means it's clear, two whistles you run, don't think",2,"What if I forget?",1,"One bird's fine, two birds are fighting, that's how you remember",2,"That's the dumbest thing I ever heard, and I'll never forget it"}},
{"fw_ld5_scout_c032","plan",2,"reg=civilian,family,worker,rescue|day=2,30|hour=18,4|mood=calm",{1,"If it's clear I blink the flashlight twice from upstairs",2,"Twice, and if it's not?",1,"Then no blink, you don't come, you go to the church, you don't wait",2,"I'll wait! Whatever you say, I'm gonna wait, so blink twice"}},
{"fw_ld5_scout_c033","plan",2,"reg=civilian,family,worker,rescue|day=1,30|hour=10,18|mood=fear",{1,"I'm back by dark or you leave, understood?!",2,"I'm not leaving",1,"You leave, you take the kids, you go to the church, nothing else",2,"Then you better come back by dark, because I'm not leaving without you, so do it"}},
{"fw_ld5_stay_c034","plan",2,"reg=civilian,family,worker,rescue|mood=sad",{1,"Leave me here, I'll slow you down, the ankle's done",2,"We're not leaving you",1,"You are, you have to, I got a pistol, a lock, a jug of water",2,"We come back tomorrow, noon tomorrow, I'm not asking, I'm telling you"}},
{"fw_ld5_stay_c035","plan",2,"reg=family|day=1,30|mood=calm",{1,"Somebody stays with the kids and it ain't gonna be me",2,"Why not you?",1,"I'm the one that can shoot, you're the one they listen to",2,"...Fine",2,"the kids stay with me, and you come back, you hear?"}},
{"fw_ld5_stay_c036","plan",2,"reg=family|mood=sad",{1,"Papaw won't leave the house, says he was born in that bed",2,"Tell him he's about to die in it",1,"You tell him! He'll whup you with the cane",2,"We leave him water and beans and a shotgun, we come back, I'm sorry but we're going"}},
{"fw_ld5_stay_c037","plan",2,"reg=civilian,family,worker,rescue|mood=funny",{1,"We leave the dog to guard the house",2,"The dog's scared of the vacuum cleaner",1,"The dog's scared of EVERYTHING, that's what makes him good, he barks first",2,"Barks, then hides under the bed, sure, we leave the dog"}},
{"fw_ld5_watch_c038","plan",2,"reg=civilian,family,worker,rescue|day=1,30|hour=19,5|mood=calm",{1,"Two hours each, and you wake the next one, you don't just stop watching",2,"I fall asleep at two hours",1,"Then you get one hour, the short one, I'll take the two",2,"One hour, I can live with that"}},
{"fw_ld5_scout_c039","plan",2,"reg=civilian,family,worker,rescue|mood=calm",{1,"If we meet anybody I do the talking, nobody else says a word",2,"Why you?",1,"Because I can lie, you turn red",2,"...Fine, I'll look at my shoes"}},
{"fw_ld5_scout_c040","plan",2,"reg=civilian,family,worker,rescue|mood=grim",{1,"I go have a look, then I come straight back. I'm not going inside",2,"What-- what if somebody's in there, hurt?",1,"If somebody's hurt, I come back. We decide what to do, both of us",2,"...Alright. Take the shotgun with you"}},
{"fw_ld5_scout_c041","plan",3,"reg=civilian,family,worker,rescue|day=1,14|mood=fear",{1,"W-who the hell's carrying the shotgun?",2,"Not me, I never shot one",3,"I did once, at a can",1,"Then it's you, one can's more than the rest of us got",3,"Oh God, okay, okay"}},
{"fw_ld5_stay_c042","plan",2,"reg=civilian,family,worker,rescue|day=2,30|mood=calm",{1,"Two go, two stay, we switch tomorrow",2,"Who goes?",1,"Me and Pete, we're the loud ones, we look like we belong",2,"Loud isn't a plan",1,"It's what we got, the quiet ones stay with the baby"}},
{"fw_ld5_stay_c043","plan",2,"reg=civilian,family,worker,rescue|day=1,30|mood=angry",{1,"We all go, NOBODY stays, I'm not leaving anybody behind in this goddamn house",2,"Even the baby? Even Mamaw?",1,"EVERYBODY! If we go we go, I'm done splitting up",2,"Get Mamaw's chair, get the diaper bag, somebody find her teeth"}},
{"fw_ld5_scout_c044","plan",2,"reg=rescue|role=rescue_firefighter|day=1,30|mood=calm",{1,"Station's four blocks, I'll check the engine bay, you watch the corner",2,"You're not going in alone, Chief taught us better than that",1,"Chief's not here to teach us anything else",2,"...I'm at the door, two minutes, you're not out I'm coming in, understood?"}},
{"fw_ld5_scout_c045","plan",2,"reg=rescue|role=rescue_medical|mood=grim",{1,"If we find people we look at them before we bring them in, no exceptions",2,"Look for what?",1,"Bites, scratches, fever, anything, I see their arms before they come near us",2,"Even a kid?",1,"Especially a kid, I'm sorry, but especially"}},
{"fw_ld5_scout_c046","plan",2,"reg=rescue|role=rescue_clergy|mood=warm",{1,"I'll go by the Hendersons', they're not church people, but they'll open up for a preacher",2,"What if they don't?",1,"Then I'll pray on the porch and come home, that's all I can do",2,"I'm coming with you, I'd rather not have you standing on a porch alone"}},
{"fw_ld5_scout_c047","plan",2,"reg=civilian,family,worker,rescue|hour=3,5|mood=angry",{1,"Everybody up, five minutes, bags packed, boots on",2,"It's four in the morning!",1,"That's why! Nobody's out there at four, so we go NOW",2,"...I hate you, I really do, give me my boots"}},
{"fw_ld5_scout_c048","plan",2,"reg=family|day=1,30|mood=calm",{1,"The boy says he can run to the corner and look, he's--",2,"No",1,"He's fifteen, he's the fastest one we got",2,"I said no, I'll go, he can watch from the window, that's his job"}},
{"fw_ld5_stay_c049","plan",2,"reg=civilian,family,worker,rescue|mood=grim",{1,"If I'm not back by noon tomorrow, don't come looking",2,"That's a stupid thing to say to somebody",1,"It's a smart thing to say, I'm saying it so you'll do it",2,"No promises, you hear me, NO promises"}},
{"fw_ld5_scout_c050","plan",3,"reg=civilian,family,worker,rescue|day=1,20|mood=fear",{1,"Who wants to check the barn?!",2,"Not me",3,"Not me either",1,"Then it's me, as usual, NOBODY ever wants to check the barn",2,"...Wait, I'll go, but I'm not going in, I'll hold the door"}},
{"fw_ld5_food_c051","plan",2,"reg=civilian,family,worker,rescue|day=3,30|mood=grim",{1,"It's peanut butter AGAIN, goddamn it, I can't, I physically can't",2,"There's four jars",1,"Four jars and no bread, we ate the bread Sunday",2,"We find bread, or flour, or something to put it on, okay?",1,"A spoon, I'm just gonna use a spoon, I'll cry later"}},
{"fw_ld5_food_c052","plan",2,"reg=family|day=5,200|mood=warm",{1,"Mrs. Dobbs's garden's still got tomatoes, hanging there red as anything",2,"Somebody's gonna pick 'em",1,"We pick 'em first, that's what a garden's for, I'll leave her a note",2,"We take half and leave half, that's fair, I'll say a prayer for her"}},
{"fw_ld5_food_c053","plan",2,"reg=worker|mood=calm",{1,"Creek's got catfish, I seen 'em from the bridge, big as my arm",2,"We got no poles",1,"Hardware's got line and hooks, I'll tie a can on a string, my granddaddy did",2,"I'll dig worms, and we eat fish tomorrow, finally, a plan"}},
{"fw_ld5_food_c054","plan",2,"reg=civilian,family,worker,rescue|day=4,40|mood=calm",{1,"Squirrels all over the Tatum place, a hundred of 'em, fat as cats",2,"I ain't eating squirrel",1,"You'll eat squirrel and thank me, we got thirty .22 rounds and nothing else to spend 'em on",2,"...Okay, you shoot, I skin, don't tell me what it tastes like"}},
{"fw_ld5_food_c055","plan",2,"reg=civilian,family,worker,rescue|day=2,30|mood=funny",{1,"Mrs. Hollis's chickens are running loose, eggs everywhere, nobody's collecting",2,"Eggs! REAL eggs!",1,"And the chickens, if we're being honest, but I'm starting with eggs, I'm NOT a monster",2,"I'll bring a basket, you bring a grandma voice to talk 'em down"}},
{"fw_ld5_food_c056","plan",2,"reg=civilian,family,worker,rescue|day=3,30|mood=grim",{1,"Forty cans, five people, I did the math, that's eight days at a can a day",2,"Eight days",1,"That's barely staying alive, I did the math twice",2,"So we got eight days to find more, I'd rather start NOW than on day seven"}},
{"fw_ld5_food_c057","plan",2,"reg=civilian,family,worker,rescue|day=5,40|mood=angry",{1,"Half a can now. Save half for later. That's what we're doing",2,"You get to decide what I eat now? Who put you in charge of the goddamn food?",1,"I can count. Whole cans and we're out Tuesday, so it's half!",2,"Fine. Half. I'm eating mine slow, and I don't want you watching"}},
{"fw_ld5_food_c058","plan",2,"reg=family|day=4,40|mood=calm",{1,"We need salt, a lot of it, Mamaw says you can't put up anything without salt",2,"Put up what?",1,"Anything! Beans, meat, fish, the grocery's got a whole aisle of it",2,"Cheapest thing in the store and the most important, I'll carry ten pounds"}},
{"fw_ld5_food_c059","plan",2,"reg=civilian,family,worker,rescue|day=3,20|hour=7,18|mood=warm",{1,"Farm stand out on 31W's got corn, beans, cucumbers, it's all just sitting there",2,"Ripe?",1,"It's July, it's ripe, it's also rotting, we got a day or two before it's mush",2,"We go today, bring every bag, pick till we can't carry no more"}},
{"fw_ld5_food_c060","plan",2,"reg=family|day=3,30|mood=sad",{1,"The little one won't eat, she just pushes it around the plate",2,"She's scared, we're all scared",1,"I know, but I can see her ribs, I need something sweet, anything",2,"Candy store by the bank, I'll go, hard candy, a lollipop, that's what we need"}},
{"fw_ld5_ammo_c061","plan",2,"reg=civilian,family,worker,rescue|day=3,30|mood=grim",{1,"Seven rounds, SEVEN, that's all that's left for the pistol",2,"We don't spend seven rounds on ANYTHING that don't need it",1,"That's what I'm saying, we find a store, or a deputy, or a dead cop with a belt",2,"A dead cop with a belt, that's what it's come to, fine, but I'm not looking"}},
{"fw_ld5_ammo_c062","plan",2,"reg=worker|day=2,30|mood=calm",{1,"Farm supply's got shells, twelve-gauge, boxes of 'em, deer season stock",2,"It ain't deer season",1,"It's always deer season at a farm supply, they stock up in June",2,"That's our next stop, we take every box, I don't care what it weighs"}},
{"fw_ld5_ammo_c063","plan",2,"reg=civilian,family,worker,rescue|mood=calm",{1,"Save the bullets if there's another way. A gunshot can bring more trouble than the one in front of you",2,"Bat only works if they're close",1,"That's the point, you don't let 'em get close, you go around, you don't pick a fight",2,"I hate it when you're right, and I hate that you say it so calm"}},
{"fw_ld5_ammo_c064","plan",2,"reg=civilian,family,worker,rescue|day=3,30|mood=calm",{1,"Buck's Outdoors on the bypass, deer rifles, shells, bows, a whole wall",2,"Buck's is where everybody in the county goes",1,"They been there already, we're late, but there's always something on the floor",2,"Always, my daddy used to pick brass up off the range, he'd find rounds under the benches"}},
{"fw_ld5_ammo_c065","plan",2,"reg=civilian,family,worker,rescue|day=4,40|mood=funny",{1,"My brother loads his own shells, he's got a press, powder, primers, the whole garage",2,"Your brother's a nerd",1,"My brother's a nerd with four hundred shells, so be nice",2,"I'm being nice, I'm being SO nice, let's go see the nerd"}},
{"fw_ld5_ammo_c066","plan",2,"reg=civilian,family,worker,rescue|day=1,14|mood=fear",{1,"Nobody fires unless I say, not for anything, not a dog, not a cat",2,"What if it's one of them?",1,"You walk away, a gunshot brings ten more, I seen it",2,"Walk away, you got it, finger off the trigger, I'm not that stupid"}},
{"fw_ld5_leave_c067","plan",2,"reg=civilian,family,worker,rescue|day=1,30|hour=18,4|mood=calm",{1,"We leave at first light, not a minute after, before the heat",2,"What the hell time's that?",1,"Five, five-thirty, set your head to it, I'll wake everybody",2,"I'll be up, I haven't slept in three days, that's not a problem"}},
{"fw_ld5_leave_c068","plan",2,"reg=civilian,family,worker,rescue|day=2,30|mood=sad",{1,"We can't go till Dale's fever breaks, I don't care what time it is",2,"It's been two days",1,"Then it's two more, I'm not carrying him in this",2,"If it hasn't broke by tomorrow we talk about carrying him"}},
{"fw_ld5_leave_c069","plan",2,"reg=civilian,family,worker,rescue|day=2,30|hour=5,10|mood=sad",{1,"We-- we go after we bury him, not before, I don't care what's out there",2,"That'll take all morning",1,"Then it takes all morning, he's not staying on the porch",2,"...Okay, I'll dig, you find a sheet"}},
{"fw_ld5_leave_c070","plan",2,"reg=civilian,family,worker,rescue|mood=angry",{1,"We go NOW, no more talking, I'm sick of talking",2,"We haven't finished the list",1,"The list is where we're GOING, shut up, get your goddamn bag",2,"Yes, boss, I'm going, I'm going"}},
{"fw_ld5_leave_c071","plan",2,"reg=worker|day=2,30|mood=calm",{1,"We leave when the tank's full, not before",2,"Tank's half",1,"Half is half a trip, I ain't breaking down in the middle of nowhere",2,"Full tank, then, I go to the Boyd place and siphon, ninety minutes"}},
{"fw_ld5_leave_c072","plan",2,"reg=civilian,family,worker,rescue|day=1,30|mood=calm|world=rain",{1,"We leave when the rain stops, not before, I'm not walking in this",2,"It might not stop",1,"It always stops, my daddy used to say rain always stops, it just don't say when",2,"I'll boil coffee, if there's any coffee, there's no coffee"}},
{"fw_ld5_leave_c073","plan",2,"reg=civilian,family,worker,rescue|hour=6,12|mood=calm",{1,"How long would you wait if your brother said he'd meet you?",2,"Till the time he told me",1,"I'd probably keep giving him another hour. Hard thing to put a deadline on",2,"I'd want to leave a note. Not pretend leaving meant I didn't care"}},
{"fw_ld5_leave_c074","plan",2,"reg=civilian,family,worker,rescue|mood=grim",{1,"Tomorrow we go, no matter what, no more waiting on anybody",2,"What if they come back?",1,"They'll find the note, if they can read, if they're ALIVE",2,"Write it big, put it on the wall where the light hits it"}},
{"fw_ld5_leave_c075","plan",2,"reg=family|mood=sad",{1,"I'm not ready to leave this house",2,"Nobody's ready",1,"Thirty years, my whole married life, I painted that kitchen yellow myself",2,"I know, I know, take the picture off the wall, it's what we can carry"}},
{"fw_ld5_fallback_c076","plan",2,"reg=civilian,family,worker,rescue|mood=grim",{1,"If it goes bad you don't help me, you go to the church, understood?",2,"I'm not leaving you",1,"You are, I'm not asking, it goes bad you go, I'll catch up if I can",2,"...Church, I got it, I hate it, but I got it"}},
{"fw_ld5_fallback_c077","plan",2,"reg=civilian,family,worker,rescue|mood=fear",{1,"If we're chased we drop the bags, drop everything, run",2,"My bag has all the medicine!",1,"You run with the medicine, I run with the water, nobody stops",2,"Nobody stops, okay, I'm saying it out loud so I remember"}},
{"fw_ld5_fallback_c078","plan",2,"reg=civilian,family,worker,rescue|mood=calm",{1,"If we split we run different ways and meet at the pond behind the Hollis farm",2,"The pond with the dock?",1,"That one, we wait two hours, then we go to the second place",2,"What the hell second place? You never told me about a second place",1,"...I'm still thinking about the second place, I'll tell you when I know"}},
{"fw_ld5_fallback_c079","plan",2,"reg=civilian,family,worker,rescue|day=1,14|mood=fear",{1,"If it's a lot of them we don't fight, we hide, we let 'em pass",2,"Hide where?",1,"Nearest building, quiet, we wait",2,"And if the building's got its own problems inside?!",1,"So we pick the next building, God, I don't know, I'm making this up as I go"}},
{"fw_ld5_fallback_c080","plan",2,"reg=civilian,family,worker,rescue|mood=sad",{1,"If I get bit, you don't wait to see, you don't even--",2,"Don't say that",1,"I'm saying it so you'll do it, I need you to promise, I need it",2,"...I promise, and I hope to God I NEVER have to"}},
{"fw_ld5_fallback_c081","plan",2,"reg=civilian,family,worker,rescue|day=2,30|mood=calm",{1,"If we're in trouble we say a word, any word, so the others know",2,"What the hell word?",1,"Peaches, if I say peaches it's bad",2,"We got a hundred jars of peaches, you're gonna say peaches all day",1,"Pickles, then, I don't care, pick a word"}},
{"fw_ld5_fallback_c082","plan",2,"reg=civilian,family,worker,rescue|day=1,14|mood=fear",{1,"If they come at us I'll draw 'em off, you take the kids north",2,"You're not drawing anybody off",1,"I'm the fastest one here, and I know the ditch behind the church",2,"You're the loudest, not the fastest, but fine, you draw 'em, I take everybody north, I don't look back"}},
{"fw_ld5_fallback_c083","plan",2,"reg=civilian,family,worker,rescue|day=3,40|mood=calm",{1,"Every morning at nine one of us goes by the water tower, in case somebody left word",2,"Somebody leaves word, we find 'em, that's a plan",1,"It's a thread, and I ain't letting anybody get lost in this county",2,"I'll go tomorrow, I'll leave a chalk arrow so they know I was there"}},
{"fw_ld5_idle_c084","plan",2,"reg=civilian,family,worker,rescue|day=3,30|mood=angry|world=inside,building",{1,"Three days of staring at that wall, I know every crack in it",2,"You-- you got a better idea than sitting in here?!",1,"ANYTHING is a better idea than sitting in here!",2,"Pick a place, one building, we go look at it TOMORROW, no more talking"}},
{"fw_ld5_idle_c085","plan",2,"reg=civilian,family,worker,rescue|day=4,40|mood=grim|world=inside",{1,"It's too quiet in here, nobody's coming",2,"Nobody was ever coming, you know that",1,"I know, it's just, I keep listening for a truck",2,"We go find the truck, whatever's out there, I'd rather look than listen"}},
{"fw_ld5_idle_c086","plan",2,"reg=civilian,family,worker,rescue|day=3,30|mood=angry",{1,"Every day we say tomorrow, and every day it's the same couch",2,"So you pick, you always say I NEVER pick",1,"The Kroger, we hit the Kroger, I'm putting my boots on right now",2,"...Then I'm coming, damn it, wait for me"}},
{"fw_ld5_idle_c087","plan",2,"reg=civilian,family,worker,rescue|day=5,60|mood=funny",{1,"If I hear one more game of gin rummy I'm gonna scream",2,"You lose at gin rummy",1,"I lose because I'm NOT paying attention, I'm paying attention to the clock on the wall that doesn't move",2,"The clock stopped Friday, dummy, let's go outside, I'll show you something to pay attention to"}},
{"fw_ld5_idle_c088","plan",2,"reg=civilian,family,worker,rescue|day=2,20|mood=calm",{1,"Nobody wants to lead, that's why we're still here",2,"I'll lead",1,"You'll lead?",2,"School, church, back here for supper, any complaints?",1,"...No, no complaints, wow, okay"}},
{"fw_ld5_idle_c089","plan",2,"reg=civilian,family,worker,rescue|day=4,40|mood=grim",{1,"Stop talking about it and go, I'm begging you",2,"We're planning!",1,"You've been planning since Monday! MONDAY! Nobody's even laced a boot!",2,"...Fair, I'm going, I'm gonna go right now, watch me"}},
{"fw_ld5_argue_c090","plan",2,"reg=civilian,family,worker,rescue|mood=angry",{1,"Remember when you said that pharmacy was safe and Pete came back hurt?",2,"I said it was SAFER, I never said safe",1,"That's the same thing when you're the one holding him down!",2,"You're right. I was wrong. I won't call a place safe just because I want it to be"}},
{"fw_ld5_argue_c091","plan",2,"reg=civilian,family,worker,rescue|day=3,30|mood=sad",{1,"I'm not going to the school, don't ask me again",2,"Nobody's making you",1,"My son was in that school, don't you understand? I can't walk past the front steps",2,"We go around it, I'll do the school, you hold the corner, whatever you can do, you do"}},
{"fw_ld5_argue_c092","plan",2,"reg=civilian,family,worker,rescue|mood=angry",{1,"My way's faster, we take the damn highway",2,"Your way's how we lost Pete",1,"You don't get to say that!",2,"I'm saying it because it's true, and because I'm tired of burying people for speed"}},
{"fw_ld5_argue_c093","plan",2,"reg=civilian,family,worker,rescue|day=2,14|mood=angry",{1,"We vote",2,"No",1,"You, you don't want a vote?!",2,"Votes are for people who aren't bleeding, I'm bleeding, I say we go, you can vote on the way"}},
{"fw_ld5_argue_c094","plan",2,"reg=civilian,family,worker,rescue|day=3,30|mood=angry",{1,"You don't get a say, you've been here two days",2,"I-- I got a say if I'm the one carrying the bag",1,"Then carry the bag and shut up about the route",2,"...No, I'm done carrying your damn bag, I'm going to the church, you do what you want"}},
{"fw_ld5_argue_c095","plan",2,"reg=civilian,family,worker,rescue|mood=funny",{1,"Nobody asked you",2,"I asked me",1,"That doesn't count",2,"It counts to me, I'm the one standing here, which way are we going?"}},
{"fw_ld5_doubt_c096","plan",2,"reg=civilian,family,worker,rescue|day=1,30|mood=fear",{1,"What if there's nothing there?",2,"Then we know",1,"I-- I don't wanna know, I wanna find something, a can of peaches, a bed",2,"...So do I, so do I, but we won't find 'em sitting here"}},
{"fw_ld5_doubt_c097","plan",2,"reg=civilian,family,worker,rescue|day=1,14|mood=fear",{1,"What if they're waiting for us?",2,"Who?",1,"I don't know! Them! Anybody!",2,"We find out together, that's the only way I know"}},
{"fw_ld5_doubt_c098","plan",2,"reg=civilian,family,worker,rescue|mood=sad",{1,"I don't think we're gonna make it",2,"Think quieter",1,"I'm serious",2,"So am I, think it, don't say it, shoes on"}},
{"fw_ld5_doubt_c099","plan",2,"reg=civilian,family,worker,rescue|day=2,30|mood=grim",{1,"Is this even the right way? We've been walking an hour",2,"You want to stand here till we figure it out? Keep walking",1,"Don't be a smartass",2,"I'm not trying to be a smartass. I'm scared too. Walking's easier if I don't think about it"}},
{"fw_ld5_joke_c100","plan",2,"reg=civilian,family,worker,rescue|mood=funny",{1,"What's the plan?",2,"Plan A is we go",1,"And plan B?",2,"We run",1,"What's plan C?",2,"We stopped at B, I was counting on A"}},
{"fw_ld5_joke_c101","plan",2,"reg=civilian,family,worker,rescue|day=1,30|mood=funny",{1,"We'll be back by supper",2,"You say that every time",1,"And I was back every time, wasn't I?",2,"Barely, your hair's gone gray since Friday"}},
{"fw_ld5_joke_c102","plan",2,"reg=civilian,family,worker,rescue|mood=funny",{1,"Last one to the pharmacy has to check the bathroom",2,"There's always a bathroom",1,"There's always a bathroom and it's always the worst one, that's why it's a race",2,"...I'm not racing, I'm walking, quickly, with intent"}},
{"fw_ld5_joke_c103","plan",2,"reg=civilian,family,worker,rescue|mood=funny",{1,"I'm bringing my lucky hat",2,"It's a Cardinals cap, you got it at a gas station",1,"It's lucky, it was on my head when we got out of the house",2,"Then it stays on, I'm never taking it off you"}},
{"fw_ld5_joke_c104","plan",2,"reg=civilian,family,worker,rescue|mood=funny",{1,"No, no dying until after we find the Kroger",2,"That's a high bar",1,"I need a cold pop, one cold pop, then you can have me",2,"Even I wouldn't make that deal, you're asking God for a refrigerator"}},
{"fw_ld5_trade_c105","plan",2,"reg=worker|day=2,30|mood=calm",{1,"Truck needs a fuel pump, I know the part number by heart, it's the one for the 302",2,"Auto parts on Dixie",1,"They'd have three on the shelf, a gasket, a tube of that gray goop",2,"I'm coming, I'm carrying, you're the mechanic, you tell me what's what"}},
{"fw_ld5_trade_c106","plan",2,"reg=rescue|role=rescue_medical|mood=calm",{1,"We set up the aid station at the church, a table, a lamp, boiled water",2,"People will come",1,"People are already coming, that's why I'm moving us there, we can't do this in a garage",2,"I'll get the table, you get the instruments, somebody find a lot of sheets"}},
{"fw_ld5_trade_c107","plan",2,"reg=rescue|role=rescue_clergy|mood=warm",{1,"I hold service at noon in the fellowship hall, whoever wants to come, comes",2,"And after?",1,"After, we go, I'll have said what I had to say, we'll go lighter",2,"Noon, then, I'll tell the others, even the ones who don't pray"}},
{"fw_ld5_trade_c108","plan",2,"reg=rescue|role=rescue_firefighter|day=1,20|mood=calm",{1,"The hydrant on the corner might still have pressure, the tower's gravity feeds it",2,"Might",1,"Fill every bucket we got, in case it quits tomorrow, I'll take the key from the truck",2,"Hydrant wrench, yeah, I got one on my belt, let's go"}},
{"fw_ld5_trade_c109","plan",2,"reg=worker|day=3,40|mood=calm",{1,"Plant's got two generators in the back, big ones, we only need the small one",2,"Small one weighs three hundred pounds",1,"Dolly, ramp, six guys, we've moved heavier at the loading dock on a Friday",2,"Six guys, where are we getting six guys?"}},
{"fw_ld5_close_c110","plan",2,"reg=civilian,family,worker,rescue|mood=calm",{1,"Say it back to me, so I know you heard",2,"We go to the Kroger, the back way, two in, two out",1,"And?",2,"If it's bad, we don't wait, we meet at the church",1,"Good, you heard, now eat something"}},
{"fw_ld5_close_c111","plan",2,"reg=civilian,family,worker,rescue|mood=calm",{1,"Whoever's last out locks it",2,"Why lock it? Nobody's coming back",1,"Habit, my mother taught me, you lock up when you leave",2,"...Fine",2,"I'll lock it, I'll feel stupid, I'll do it anyway"}},
{"fw_ld5_close_c112","plan",3,"reg=civilian,family,worker,rescue|mood=grim",{1,"Anybody who's changing their mind says so now, five minutes, after that you're coming",2,"I'm NOT changing my mind",3,"Me neither",1,"That's done, boots on, we go in five"}},
{"fw_ld5_close_c113","plan",2,"reg=civilian,family,worker,rescue|mood=calm",{1,"Write it on the wall so nobody can say they forgot",2,"Write what?",1,"The place, the time, the one who's going, put my name on it",2,"Your name's on a wall in lipstick, that's a first, but fine"}},
{"fw_ld5_close_c114","plan",3,"reg=civilian,family,worker,rescue|mood=calm",{1,"Everybody knows their job? If you don't, ask now, not at the door",2,"I carry water",3,"I watch the street",1,"And I knock, you two do the rest, go"}},
{"fw_ld5_close_c115","plan",2,"reg=civilian,family,worker,rescue|mood=angry",{1,"Done, we go, no vote",2,"You can't just decide",1,"I just did, ten minutes ago, you were there",2,"...I was there, I was just hoping you'd change your mind"}},
{"fw_ld5_dentist_c116","plan",2,"reg=civilian,family,worker,rescue|day=3,30|mood=sad",{1,"Dentist on Third, Dr. Hale, he's got a drawer of those little clove oil bottles",2,"For what?",1,"For my tooth, I haven't slept since Sunday, it's like somebody's driving a nail in",2,"We go now, I don't care if it takes all day, I'm not listening to you moan another night"}},
{"fw_ld5_naming_c117","plan",2,"reg=civilian,family,worker,rescue|day=2,30|mood=funny",{1,"Every plan should have a name",2,"Why?",1,"So we can call it something, Operation Peaches, we take the pharmacy, we eat peaches",2,"We're not calling it Operation Peaches",1,"Then Operation Not Dying, it's got a ring to it"}},
{"fw_ld5_smoke_c118","plan",2,"reg=civilian,family,worker,rescue|day=2,20|mood=funny",{1,"Last pack of cigarettes, we split it, we quit",2,"You said that yesterday",1,"Yesterday was a different last pack, this is THE last pack",2,"We find a store, we get more, we quit next week, I mean it, next week"}},
{"fw_ld5_trade_c119","plan",2,"reg=civilian,family,worker,rescue|day=3,30|mood=calm",{1,"The folks at the Hollis farm want salt, and we got salt",2,"What do they have?",1,"Eggs, a dozen a day, plus they got a milk cow, they said we can have some",2,"We walk the salt over now, I'm tired of canned peaches, I want a cup of milk"}},
{"fw_ld5_map_c120","plan",2,"reg=civilian,family,worker,rescue|mood=calm",{1,"I'm marking the map, red pins for places we've been, blue for places we're going",2,"You have pins?",1,"Pushpins from the bulletin board, I'm a very organized person",2,"Great, now we can see how little we've done, I'm so excited"}},
{"fw_ld5_civlaw_d001","plan",2,"r1=civilian,family,worker,rescue|r2=law,swat|day=0,4|mood=fear",{1,"They're on every street we try, officer, you're the only one with a badge, where do we GO?",2,"Gym's out, I looked, the church on Elm maybe, if the pastor opened it",1,"Maybe! You said maybe!",2,"I said maybe 'cause I don't lie to people, c'mon, we look at it together"}},
{"fw_ld5_civlaw_d002","plan",2,"r1=civilian,family,worker,rescue|r2=law|x2=m|day=1,10|mood=angry",{1,"You said the bridge, Hale, you told us the bridge was open",2,"Hell, it was open Friday, I never said it'd STAY open",1,"So now what?!",2,"Now the boat landing at Rosewood, if anybody's running boats, if nobody is we think again"}},
{"fw_ld5_civlaw_d003","plan",2,"r1=civilian,family,worker,rescue|r2=law|mood=calm",{1,"Does that damn radio of yours still work?",2,"Works fine, it just don't say anything, I keep it on",1,"Why keep it on?",2,"State police post in E-town had a generator, if they're up they'll key a mic someday, I wanna be listening"}},
{"fw_ld5_civlaw_d004","plan",2,"r1=civilian,family,worker,rescue|r2=law,swat|x1=f|day=3,40|mood=calm",{1,"Where do deputies go when there's no department?",2,"The station, honest answer, habit, plus the long guns are in the rack",1,"Guns, okay, I hadn't thought of the rack",2,"Nobody thinks of the rack until they need one, we go in, we take what's ours, we leave a receipt"}},
{"fw_ld5_civlaw_d005","plan",2,"r1=civilian,family,worker,rescue|r2=law|mood=grim",{1,"If we find more people, we bring 'em, right?",2,"We check 'em first, arms and legs, anybody bit stays outside",1,"And if they won't stay outside?",2,"Then I explain it with this, and I hope I never have to"}},
{"fw_ld5_civlaw_d006","plan",2,"r1=civilian,family,worker,rescue|r2=law|mood=sad",{1,"You're the cop, you decide",2,"I'm twenty-six, eleven months on the job, I'm nobody's boss",1,"You're the closest thing we got",2,"...Then you're stuck with a kid in a uniform, church, I say we go to the church"}},
{"fw_ld5_civlaw_d007","plan",2,"r1=civilian,family,worker,rescue|r2=law,swat|mood=calm",{1,"Cruiser's on fumes, so we walk or we stall",2,"County road garage has a fuel tank, they filled the plows there",1,"Pump needs power",2,"Hand crank on the side, the old boys always kept one, three miles, bring a can"}},
{"fw_ld5_civlaw_d008","plan",2,"r1=family|r2=law,swat|day=1,14|hour=11,23|mood=fear",{1,"Where would you look for somewhere children could sleep?",2,"Maybe a records room, if we could check it properly and find a way out",1,"A records room? For children?",2,"I wouldn't promise a records room or a lock I hadn't seen. Being bored beats being trapped"}},
{"fw_ld5_civlaw_d009","plan",2,"r1=civilian,family,worker,rescue|r2=law,swat|mood=calm",{1,"We should leave a sign for anybody looking, spray paint, on the road",2,"Saying what?",1,"Where we are, how many of us",2,"...Put the church and the number, not the date, the date's just for them"}},
{"fw_ld5_civlaw_d010","plan",2,"r1=civilian,family,worker,rescue|r2=law|day=1,10|mood=sad",{1,"You keep looking north, officer",2,"Last I heard, my wife was in Louisville. On shift Friday",1,"Then go, find her, we'll manage",2,"I keep setting myself a day to go. Moving the day doesn't tell me where she is"}},
{"fw_ld5_civlaw_d011","plan",2,"r1=law|r2=civilian,family,worker,rescue|day=2,30|mood=calm",{1,"You folks know the creek road? I ain't been out that way since the flood",2,"Washed out at the bridge, but you can wade it, knee deep",1,"We wade it, anything on the other side?",2,"Teague's farm, cattle and a gate, he might let us in"}},
{"fw_ld5_civlaw_d012","plan",2,"r1=law,swat|r2=civilian,family,worker,rescue|day=3,30|mood=calm",{1,"We need every truck with gas, the old folks out on the east end still aren't out",2,"You want our truck?",1,"I want you AND your truck, I can't drive 'em all",2,"So I drive, you ride shotgun, three trips, I'll bring blankets"}},
{"fw_ld5_civlaw_d013","plan",2,"r1=law,swat|r2=civilian,family,worker,rescue|day=1,14|mood=calm",{1,"How many of you? Exactly, I need a number",2,"Eleven, if you count the baby",1,"I count the baby, eleven, the church basement holds twenty",2,"That's where we sleep, and the baby's gonna be thrilled"}},
{"fw_ld5_civlaw_d014","plan",2,"r1=civilian,family,worker,rescue|r2=law,swat|day=2,30|hour=14,20|mood=calm",{1,"Why the hell do we stop so early? There's hours of light left",2,"I'd rather look for a place while we can still see the way in. Less to guess about",1,"So we sleep early",2,"Sleep early, up with the sun, I can do that, my mother raised me on a farm"}},
{"fw_ld5_civlaw_d015","plan",2,"r1=civilian,family,worker,rescue|r2=law,swat|mood=funny",{1,"Can I have a gun? I'm sick of being the only one with a spatula",2,"You ever fire one?",1,"Once, a pellet gun, at the county fair, I won a goldfish",2,"...You start with this, safety's here, aim at the middle, don't shoot unless I say"}},
{"fw_ld5_civlaw_d016","plan",2,"r1=law|r2=civilian,family,worker,rescue|day=2,30|mood=warm",{1,"I got first watch, you two get some sleep",2,"You been up since Thursday, Hale",1,"Cops don't sleep, it's in the handbook",2,"Like hell it is. Take a nap, Hale. I'll wake you at two"}},
{"fw_ld5_civlaw_d017","plan",2,"r1=civilian,family,worker,rescue|r2=law,swat|mood=calm",{1,"That notebook of yours... you've got addresses written down, haven't you?",2,"Forty people I know living alone in their houses. I get round to check on them when I can",1,"Then I'll take Oak Street, you take the other side, we meet at the corner in an--",2,"No",2,"I'm not sending you off alone. We go two by two"}},
{"fw_ld5_civlaw_d018","plan",2,"r1=law|r2=civilian,family,worker,rescue|mood=calm",{1,"I need a volunteer to check the pharmacy with me",2,"I'll do it, I used to work for the pharmacist",1,"You know the layout?",2,"Everything, I know where he kept the good stuff and where he kept the key, let's go"}},
{"fw_ld5_civlaw_d019","plan",2,"r1=civilian,family,worker,rescue|r2=law,swat|x1=f|mood=funny",{1,"Is the jail a good place to sleep?",2,"Bars on every window for a reason, ma'am",1,"The cells have beds, though",2,"The cells have bunks, a bucket, and whatever the last guy left, I'd rather the school"}},
{"fw_ld5_civlaw_d020","plan",2,"r1=civilian,family,worker,rescue|r2=law|mood=calm",{1,"Where do you get news?",2,"Truckers, the CB, channel 19, there's a rig stuck at the overpass with a battery",1,"Can we listen?",2,"We listen, we don't talk, you talk, you tell the whole county where we are"}},
{"fw_ld5_civlaw_d021","plan",2,"r1=civilian,family,worker,rescue|r2=law,swat|day=2,20|mood=calm",{1,"The Marathon's got gas in the ground, I know the owner",2,"Name?",1,"Gary Doyle, we bowl together on Thursdays",2,"Gary won't mind, we bring a note, a hand pump, a few guys who can lift"}},
{"fw_ld5_civlaw_d022","plan",2,"r1=civilian,family,worker,rescue|r2=law,swat|day=2,20|mood=angry",{1,"Why do we always go the long way?!",2,"Because the short way has a roadblock I don't wanna meet",1,"What the hell kind of roadblock?",2,"The kind with men who stopped being the Army, don't ask, just walk"}},
{"fw_ld5_civlaw_d023","plan",2,"r1=family|r2=law,swat|day=1,10|mood=fear",{1,"Where would the evac point be, if there is one?!",2,"I'd bet the armory in Brandenburg, it's got a fence, a flagpole, a gate",1,"Is that your guess or your orders?!",2,"My guess, there ain't been orders in a week"}},
{"fw_ld5_civlaw_d024","plan",3,"r1=law,swat|r2=civilian,family,worker,rescue|day=2,30|mood=calm",{1,"If we couldn't agree whether to stay or move, how would you decide?",2,"I'd want a say. I hate feeling shut in",3,"I'd want to know whether anybody needed rest first",1,"Then we'd talk about what moving actually meant. No tie-breaking vote makes a wagon appear"}},
{"fw_ld5_civlaw_d025","plan",2,"r1=civilian,family,worker,rescue|r2=law|day=3,40|mood=sad",{1,"Do you ever think this'll end?",2,"I, I think about parking tickets a lot, it helps",1,"Parking tickets?",2,"Somebody's gonna need to write 'em again, and I figure that somebody's me"}},
{"fw_ld5_civlaw_d026","plan",2,"r1=civilian,family,worker,rescue|r2=law,swat|day=2,30|mood=grim",{1,"They said the school's clear, a boy ran in and out, said nothing's moving",2,"A boy said that?",1,"He's thirteen, but he's sharp, he's been right all week",2,"Thirteen's not enough, I'm sending two men first, the boy stays out of it"}},
{"fw_ld5_milciv_d027","plan",2,"r1=civilian,family,worker,rescue|r2=military|day=0,6|mood=fear",{1,"Soldier, where does the Army take us? Somebody said Knox",2,"Knox is locked, folks, I was at the gate Saturday, NOBODY in, nobody out",1,"Then what the hell are we doing following you?!",2,"You're following me to the school, my lieutenant's got a collection point there, twelve miles",1,"...Twelve miles, shit, okay, okay"}},
}
